import{_ as s,l as i,o as e,c as n,v as t,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"快照隔离","description":"","frontmatter":{"title":"快照隔离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/snapshot-isolation.md","filePath":"cs/snapshot-isolation.md","lastUpdated":1789023840000}'),h={name:"cs/snapshot-isolation.md"};function E(A,a,_,S,m,B){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="快照隔离" tabindex="-1">快照隔离 <a class="header-anchor" href="#快照隔离" aria-label="Permalink to &quot;快照隔离&quot;">​</a></h1><div class="epigraph"><p>事务读一个已提交快照，写在提交时若写集与并发已提交者冲突则中止；它不是冲突可串行，但很常见。</p><footer>—— 据 Berenson et al., SIGMOD 1995；Reed 对多版本；Ramakrishnan 对照</footer></div><p><a href="/cs/mvcc">上一课</a>让读选可见版本、写建新版。本课不重写可见性函数。缺口是广泛实现的一种调度：<strong>快照隔离（SI）</strong>。读不取锁，提交时检查写–写。幻读与写偏斜下一课专收。隔离级别表更后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MVCC 课留下「读按快照」。SI 把快照钉在事务开始（或第一条语句），提交用「第一提交者胜」的写集冲突：与已提交的重叠写则 abort。它禁止脏读、不可重复读（对自己的快照），仍允许下一课的写偏斜。缺口是<strong>把 SI 从「有版本」里命名出来</strong>，避免当成可串行。</p><p><span class="marginnote">SSI（可串行快照隔离）后来加冲突监测逼近可串行。主干先钉经典 SI，不把 SSI 当默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开始：记 startTS。读：最新的 committedTS \\(\\lt\\) startTS 的版本（加上自己的写）。写：私有直到提交，再分配 commitTS 并检查写集。失败则整个事务撤，靠 WAL UNDO。本课不把每家数据库默认级别写成同一 SI。</p>',8)),(e(),l(c,null,{default:o(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E8%AE%B0%E5%BF%AB%E7%85%A7%E6%97%B6%E9%97%B4%22%5D%20--%3E%20READ%5B%22%E8%AF%BB%E8%AF%A5%E5%BF%AB%E7%85%A7%E5%8F%AF%E8%A7%81%E7%89%88%E6%9C%AC%22%5D%0A%20%20READ%20--%3E%20WSET%5B%22%E7%B4%AF%E7%A7%AF%E5%86%99%E9%9B%86%22%5D%0A%20%20WSET%20--%3E%20CHK%5B%22%E6%8F%90%E4%BA%A4%E6%97%B6%E5%86%99%E5%86%99%E5%86%B2%E7%AA%81%E5%88%99%E4%B8%AD%E6%AD%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SI 用版本换掉读锁，写锁或占用仍常在，避免 ww。冲突可串行要求的 rw 边可以成环而不被检测——写偏斜。后课用保险与医生的经典例子说明规格差在哪。对只读只读快照，近似理想。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把快照当备份工具（时间点恢复是日志另一用法）。哪些异常 SI 还放行，下一课幻读与写偏斜。</p><p>后课默认：SI 是 MVCC 上最常见的产品点。它还不是可串行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SI：读快照，提交查写集。</li><li>无脏读，仍可能写偏斜。</li><li>幻读与写偏斜下一课。</li><li>出处：Berenson et al., 1995；Reed 1978。</li></ul>',7))])}const f=s(h,[["render",E]]);export{u as __pageData,f as default};
